from fractions import Fraction as F
prior = {'y1': F(1, 3), 'y2': F(2, 3)}
lik = {'y1': F(3, 4), 'y2': F(1, 4)}
joint = {k: prior[k] * lik[k] for k in prior}
ev = sum(joint.values())
post = {k: joint[k] / ev for k in prior}
pred = max(post, key=post.get)
err = 1 - post[pred]
print('joint', joint, 'evidence', ev)
print('posterior', post, 'predict', pred)
print('P(misclassify x) =', err, '=', float(err), '->', round(float(err), 2))
